class Solution {
    public int maxSubArray(int[] nums) {
        int best = Integer.MIN_VALUE;
        for (int i = 0; i < nums.length; i++) {
            int sum = 0;
            for (int j = i; j < nums.length; j++) {
                sum += nums[j];
                best = Math.max(best, sum);
            }
        }
        return best;
    }
}

class Solution {
    public int maxSubArray(int[] nums) {
        return solve(nums, 0, nums.length - 1);
    }

    private int solve(int[] a, int lo, int hi) {
        if (lo == hi) return a[lo];
        int mid = lo + (hi - lo) / 2;
        int leftMax  = solve(a, lo, mid);
        int rightMax = solve(a, mid + 1, hi);

        int sum = 0, lBest = Integer.MIN_VALUE;
        for (int i = mid; i >= lo; i--) {
            sum += a[i];
            lBest = Math.max(lBest, sum);
        }
        sum = 0;
        int rBest = Integer.MIN_VALUE;
        for (int i = mid + 1; i <= hi; i++) {
            sum += a[i];
            rBest = Math.max(rBest, sum);
        }
        return Math.max(Math.max(leftMax, rightMax), lBest + rBest);
    }
}

class Solution {
    public int maxSubArray(int[] nums) {
        int cur = nums[0];
        int best = nums[0];
        for (int i = 1; i < nums.length; i++) {
            cur = Math.max(nums[i], cur + nums[i]);
            best = Math.max(best, cur);
        }
        return best;
    }
}
